class DataAnalytics:
    def mean(self, data):
        return sum(data) / len(data)

    def median(self, data):
        data = sorted(data)
        n = len(data)
        if n % 2 == 1:
            return data[n // 2]
        else:
            return (data[n // 2 - 1] + data[n // 2]) / 2

    def mode(self, data):
        frequency = {}
        for item in data:
            if item in frequency:
                frequency[item] += 1
            else:
                frequency[item] = 1
        most_frequent = max(frequency.values())
        modes = [key for key, value in frequency.items() if value == most_frequent]
        return modes

    def variance(self, data):
        mean = self.mean(data)
        return sum((x - mean) ** 2 for x in data) / len(data)

    def standard_deviation(self, data):
        return self.variance(data) ** 0.5

    def percentile(self, data, percentile):
        data = sorted(data)
        index = int(percentile / 100 * len(data))
        return data[index]

import pytest
from analytics import DataAnalytics

da = DataAnalytics()

def test_mean():
    assert da.mean([1, 2, 3, 4, 5]) == 3

def test_median():
    assert da.median([3, 1, 2, 5, 4]) == 3
    assert da.median([3, 1, 2, 5, 4, 6]) == 3.5

def test_mode():
    assert da.mode([1, 2, 2, 3, 4]) == [2]
    assert da.mode([1, 1, 2, 2, 3]) == [1, 2]

def test_variance():
    assert pytest.approx(da.variance([1, 2, 3, 4, 5]), 2.5)

def test_standard_deviation():
    assert pytest.approx(da.standard_deviation([1, 2, 3, 4, 5]), 1.58)

def test_percentile():
    assert da.percentile([1, 2, 3, 4, 5], 40) == 2

